with operational_tenant as (
  select id from logos_academy.tenants where slug='logos-academy' and deleted_at is null
), activities as (
  select value d from explorer_v2_activities cross join lateral jsonb_array_elements(payload)
)
insert into logos_academy.lesson_templates (
  id,tenant_id,cycle_id,position,title,objective,reference_content,estimated_activity_minutes
)
select md5('logos-academy-explorer-v2-lesson-'||(d->>'position'))::uuid,t.id,
  md5('logos-academy-explorer-v2-cycle-'||(((d->>'position')::int-1)/4+1))::uuid,
  (((d->>'position')::int-1)%4+1)::smallint,d->>'title',d->>'objective',d->>'context',
  case when (d->>'position')::int in (4,8,12,16) then 45 else 25 end
from operational_tenant t cross join activities
on conflict do nothing;

with operational_tenant as (
  select id from logos_academy.tenants where slug='logos-academy' and deleted_at is null
), activities as (
  select value d from explorer_v2_activities cross join lateral jsonb_array_elements(payload)
)
insert into logos_academy.lesson_concepts (id,tenant_id,lesson_template_id,concept_id)
select md5('logos-academy-explorer-v2-lesson-concept-'||(d->>'position'))::uuid,t.id,
  md5('logos-academy-explorer-v2-lesson-'||(d->>'position'))::uuid,
  md5('logos-academy-explorer-v1-concept-'||(d->>'position'))::uuid
from operational_tenant t cross join activities
on conflict do nothing;

with operational_tenant as (
  select id from logos_academy.tenants where slug='logos-academy' and deleted_at is null
), activities as (
  select value d from explorer_v2_activities cross join lateral jsonb_array_elements(payload)
)
insert into logos_academy.activity_templates (
  id,tenant_id,lesson_template_id,title,objective,instructions,continuity_guidance,estimated_minutes,
  context,expected_result,steps,plan_b,reflection_prompt,portfolio_evidence,tool_hint
)
select md5('logos-academy-explorer-v2-activity-'||(d->>'position'))::uuid,t.id,
  md5('logos-academy-explorer-v2-lesson-'||(d->>'position'))::uuid,d->>'title',d->>'objective',
  d->>'challenge',d->>'continuity',case when (d->>'position')::int in (4,8,12,16) then 45 else 25 end,
  d->>'context',d->>'evidence',d->'steps',d->>'planB',d->>'reflection',d->>'evidence',d->>'tools'
from operational_tenant t cross join activities
on conflict do nothing;

with operational_tenant as (
  select id from logos_academy.tenants where slug='logos-academy' and deleted_at is null
), activities as (
  select value d from explorer_v2_activities cross join lateral jsonb_array_elements(payload)
), requirements as (
  select d,(ordinality)::smallint position,value requirement
  from activities cross join lateral jsonb_array_elements(d->'requirements') with ordinality
)
insert into logos_academy.activity_requirements (id,tenant_id,activity_template_id,kind,label,is_required,position)
select md5('logos-academy-explorer-v2-requirement-'||(d->>'position')||'-'||position)::uuid,t.id,
  md5('logos-academy-explorer-v2-activity-'||(d->>'position'))::uuid,
  requirement->>0,requirement->>2,(requirement->>1)::boolean,position
from operational_tenant t cross join requirements
on conflict do nothing;

with operational_tenant as (
  select id from logos_academy.tenants where slug='logos-academy' and deleted_at is null
), activities as (
  select value d from explorer_v2_activities cross join lateral jsonb_array_elements(payload)
), criteria as (
  select d,(ordinality)::smallint position,value #>> '{}' criterion
  from activities cross join lateral jsonb_array_elements(d->'criteria') with ordinality
)
insert into logos_academy.activity_criteria (id,tenant_id,activity_template_id,label,description,position)
select md5('logos-academy-explorer-v2-criterion-'||(d->>'position')||'-'||position)::uuid,t.id,
  md5('logos-academy-explorer-v2-activity-'||(d->>'position'))::uuid,
  criterion,criterion,position
from operational_tenant t cross join criteria
on conflict do nothing;

-- Publication boundary: old rows keep working, but new classes/enrollments cannot target v1.
create or replace function private.guard_explorer_v1_new_placement()
returns trigger language plpgsql set search_path='' as $$
begin
  if new.curriculum_id = md5('logos-academy-explorer-v1-curriculum')::uuid then
    raise exception using errcode='23514',message='Explorer v1 no longer accepts new classes or enrollments';
  end if;
  return new;
end;
$$;

drop trigger if exists classes_explorer_v1_new_placement on logos_academy.classes;
create trigger classes_explorer_v1_new_placement before insert on logos_academy.classes
for each row execute function private.guard_explorer_v1_new_placement();
drop trigger if exists enrollments_explorer_v1_new_placement on logos_academy.enrollments;
create trigger enrollments_explorer_v1_new_placement before insert on logos_academy.enrollments
for each row execute function private.guard_explorer_v1_new_placement();

revoke all on function private.guard_explorer_v1_new_placement() from public,anon,authenticated;

notify pgrst,'reload schema';
commit;
